    int[] da = dedupSort(a);
    int[] db = dedupSort(b);
    int[] dc = dedupSort(c);
    long count = 0;
    for (int y : db) {
        for (int x : da) {
            if (x > y) break;          // da sorted: nothing later qualifies
            for (int z : dc) {
                if (z > y) break;
                count++;
            }
        }
