public long triplets(int[] a, int[] b, int[] c) {
    int[] da = dedupSort(a);
    int[] db = dedupSort(b);
    int[] dc = dedupSort(c);
    long total = 0;
    for (int y : db) {
        long x = upperBound(da, y);
        long z = upperBound(dc, y);
        total += x * z;
    }
    return total;
}

// number of elements <= y == index just past the last element <= y
private int upperBound(int[] arr, int y) {
    int lo = 0, hi = arr.length;
    while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (arr[mid] <= y) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

private int[] dedupSort(int[] arr) {
    return java.util.Arrays.stream(arr).distinct().sorted().toArray();
}

